-- VERIFY (after all parts): expect 6,831 inserted candidates across all parts
-- (6,848 staged rows minus 17 same-race duplicates absorbed by on conflict).
select c.status, count(*) as candidates from candidates c join races r on r.id = c.race_id join municipalities m on m.id = r.municipality_id where m.slug <> 'huntsville' group by c.status order by c.status;
